 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The horizontal multi-cell run is the motif; isolated non-background
    # cells indicate where a copy of that motif should be placed.
    runs = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start > 1:
                runs.append((c - start, r, start, row[start:c]))
    if not runs:
        return [row[:] for row in grid]
    _, mr, ms, motif = max(runs)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and not (r == mr and ms <= c < ms + len(motif)):
                start = c - len(motif) // 2
                for j, value in enumerate(motif):
                    x = start + j
                    if 0 <= x < w:
                        out[r][x] = value
    return out
